func (p *StaticHostModelPolicy) GetEventFromName(name string) (StaticHostModelEvent, bool) {
	switch name {
	case "done.invoke":
		return StaticHostModelEventDoneInvoke, true
	case "done.invoke.gen":
		return StaticHostModelEventDoneInvokeGen, true
	case "error.execution":
		return StaticHostModelEventErrorExecution, true
	case "error.invoke":
		return StaticHostModelEventErrorInvoke, true
	case "error.invoke.gen":
		return StaticHostModelEventErrorInvokeGen, true
	case "host.model.generate.request":
		return StaticHostModelEventHostModelGenerateRequest, true
	case "model.leave":
		return StaticHostModelEventModelLeave, true
	}
	return StaticHostModelEventNull, false
}

